def _to_epoch(value: "Union[int, dt.datetime, dt.date, str, pa.Scalar]", unit: str) -> int:
    """Convert a timestamp representation to an integer epoch expressed in ``unit``.

    See the module docstring / config documentation for the exact conversion rules.
    """
    # ``bool`` is a subclass of ``int`` but is never a valid timestamp.
    if isinstance(value, bool):
        raise TypeError(f"Timestamp value must not be a bool, got {value!r}")

    if isinstance(value, int):
        return value

    if isinstance(value, pa.Scalar):
        if pa.types.is_timestamp(value.type):
            return value.value
        raise TypeError(f"Timestamp value must be a timestamp scalar, got pyarrow scalar of type {value.type}")

    if isinstance(value, str):
        parsed = _parse_iso8601(value)
        if parsed is None:
            raise TypeError(f"Timestamp value must be a valid ISO-8601 date/datetime string, got {value!r}")
        value = parsed

