    if isinstance(value, dt.datetime):
        if value.tzinfo is None:
            value = value.replace(tzinfo=dt.timezone.utc)
        else:
            value = value.astimezone(dt.timezone.utc)
        return _datetime_to_epoch(value, unit)

    if isinstance(value, dt.date):
        value = dt.datetime(value.year, value.month, value.day, tzinfo=dt.timezone.utc)
        return _datetime_to_epoch(value, unit)

    raise TypeError(
        f"Timestamp value must be a int, datetime, date, ISO-8601 str or pyarrow timestamp scalar, "
        f"got {type(value).__name__}"
    )


def _parse_iso8601(value: str) -> "Optional[Union[dt.datetime, dt.date]]":
    """Parse an ISO-8601 date or datetime string, returning ``None`` if it is not valid."""
    try:
        return dt.datetime.fromisoformat(value)
    except ValueError:
        pass
    try:
        return dt.date.fromisoformat(value)
    except ValueError:
