def _datetime_to_epoch(value: dt.datetime, unit: str) -> int:
    """Convert a timezone-aware datetime to an integer epoch in ``unit`` without losing precision."""
    delta = value - _EPOCH
    total_us = (delta.days * 86_400 + delta.seconds) * 1_000_000 + delta.microseconds
    return int(round(total_us * _UNIT_PER_MICROSECOND[unit]))


@dataclass
class TsFileConfig(datasets.BuilderConfig):
    """BuilderConfig for the TsFile (Apache IoTDB time-series) packaged module."""

    input_batch_size: int = 8192
    output_batch_size: int = 1000
    columns: Optional[list[str]] = None
    timestamp_unit: str = "ms"
    on_bad_files: str = "error"
    start_time: "Optional[Union[int, dt.datetime, dt.date, str, pa.Scalar]]" = None
    end_time: "Optional[Union[int, dt.datetime, dt.date, str, pa.Scalar]]" = None
    table_name: Optional[str] = None
    timestamp_tz: Optional[str] = None

    def __post_init__(self):
        # Inherit name validation and data_files type checking from BuilderConfig.
        super().__post_init__()

        if self.input_batch_size <= 0:
            raise ValueError(f"input_batch_size must be a positive integer, got {self.input_batch_size}")
        if self.output_batch_size <= 0:
            raise ValueError(f"output_batch_size must be a positive integer, got {self.output_batch_size}")
        if self.columns is not None and len(self.columns) == 0:
            raise ValueError("columns must be a non-empty list of column names or None")
        if self.timestamp_unit not in _TIMESTAMP_UNITS:
            raise ValueError(
                f"timestamp_unit must be one of {_TIMESTAMP_UNITS}, got {self.timestamp_unit!r}"
            )
        if self.on_bad_files not in _ON_BAD_FILES:
            raise ValueError(f"on_bad_files must be one of {_ON_BAD_FILES}, got {self.on_bad_files!r}")

        # Normalize the time bounds to plain integer epochs.
        if self.start_time is not None:
            self.start_time = _to_epoch(self.start_time, self.timestamp_unit)
        if self.end_time is not None:
            self.end_time = _to_epoch(self.end_time, self.timestamp_unit)


